/* The notched outline of clerk-band. --x is where the shoulder starts: the edge of the
   content column (page width minus gutters), never closer than one gutter to the screen
   edge. The shoulder is 44px tall and 40px wide. */
.clerk-band {
  --x: max(var(--page-gutter), calc((100% - var(--page-width)) / 2 + var(--page-gutter)));
  --d: 2.75rem;
  --w: 2.5rem;
}

.clerk-band-top {
  clip-path: polygon(
    0 0, var(--x) 0, calc(var(--x) + var(--w)) var(--d), calc(100% - var(--x) - var(--w)) var(--d),
    calc(100% - var(--x)) 0, 100% 0, 100% 100%, 0 100%
  );
}

.clerk-band-bottom {
  clip-path: polygon(
    0 0, 100% 0, 100% 100%, calc(100% - var(--x)) 100%, calc(100% - var(--x) - var(--w)) calc(100% - var(--d)),
    calc(var(--x) + var(--w)) calc(100% - var(--d)), var(--x) 100%, 0 100%
  );
}

.clerk-band-both {
  clip-path: polygon(
    0 0, var(--x) 0, calc(var(--x) + var(--w)) var(--d), calc(100% - var(--x) - var(--w)) var(--d),
    calc(100% - var(--x)) 0, 100% 0, 100% 100%, calc(100% - var(--x)) 100%,
    calc(100% - var(--x) - var(--w)) calc(100% - var(--d)), calc(var(--x) + var(--w)) calc(100% - var(--d)),
    var(--x) 100%, 0 100%
  );
}

@media (min-width: 64rem) {
  .clerk-band {
    --w: 2.75rem;
  }
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./clerk-band.css";

export interface ClerkBandProps {
  children: ReactNode;
  /** step the top edge in (the section above dips into the band) */
  notchTop?: boolean;
  /** step the bottom edge in (the section below rises into the band) */
  notchBottom?: boolean;
  /** colour of the section above, shown inside the top notch */
  edgeTop?: "background" | "card";
  /** colour of the section below, shown inside the bottom notch */
  edgeBottom?: "background" | "card";
  /** dark forces the dark colours (as on the original); inherit follows the page */
  tone?: "dark" | "inherit";
  id?: string;
  className?: string;
}

const edge = { background: "bg-background", card: "bg-card" };

export function ClerkBand({
  children,
  notchTop = true,
  notchBottom = true,
  edgeTop = "card",
  edgeBottom = "background",
  tone = "dark",
  id,
  className,
}: ClerkBandProps) {
  return (
    <section id={id} className="relative isolate">
      {/* the neighbours' colours, showing through the notches */}
      {notchTop && <div aria-hidden className={cn("absolute inset-x-0 top-0 -z-10 h-12", edge[edgeTop])} />}
      {notchBottom && <div aria-hidden className={cn("absolute inset-x-0 bottom-0 -z-10 h-12", edge[edgeBottom])} />}
      <div
        className={cn(
          "clerk-band relative overflow-hidden bg-background text-foreground",
          tone === "dark" && "dark",
          notchTop && "clerk-band-top pt-11",
          notchBottom && "clerk-band-bottom pb-11",
          notchTop && notchBottom && "clerk-band-both",
          className,
        )}
      >
        {children}
      </div>
    </section>
  );
}
